/**
 * @description: User Portal Navbar (mirrors institute_portal Sidebar pattern)
 * @author: Institute User Portal
 * @date: 2026
 */
import React, { useContext } from 'react';
import { FaUserGraduate, FaUserTie, FaBus } from 'react-icons/fa';
import { AuthContext } from '../../App';

function NavbarUser() {
  const { stateAuth } = useContext(AuthContext);

  if (!stateAuth?.user) return null;

  const userType = (stateAuth.user.typ || '').toUpperCase();

  // const brandName =
  //   userType === 'STUDENT'
  //     ? 'Student Portal'
  //     : userType === 'TRANSPORT'
  //     ? 'Transport Portal'
  //     : 'Staff Portal';

  const roleIcon =
    userType === 'STUDENT' ? (
      <FaUserGraduate />
    ) : userType === 'TRANSPORT' ? (
      <FaBus />
    ) : (
      <FaUserTie />
    );

  return (
    <aside className="user-nav-sidebar">
      {/* Branding header */}
      <div className="user-nav-brand">
        <div className="user-nav-brand-icon">{roleIcon}</div>
        <div className="user-nav-brand-text">
          <h4>{brandName}</h4>
          <span>{stateAuth.user.emlid}</span>
        </div>
      </div>
    </aside>
  );
}

export default NavbarUser;
